#!/usr/bin/env node
/**
 * MUGA: generate-comparison-benchmark — A6 / A7 (#461).
 *
 * Reads the latest benchmark JSON report from
 * tests/benchmark/reports/*-muga.json and replaces the section
 * between the BENCHMARK_START / BENCHMARK_END markers in
 * docs/comparison.html with auto-generated content.
 *
 * The script is surgical: it ONLY touches the bytes between markers.
 * Everything else in comparison.html — the hand-written feature
 * matrix, footnotes, methodology — stays exactly as committed.
 *
 * Generated content includes:
 *   - A summary table of byCompetitor match rates
 *   - A category breakdown for MUGA (per corpus directory)
 *   - A footer with the report timestamp + source paths so a reader
 *     can retrace the numbers
 *
 * Per-URL drill-down: emitted as a collapsible <details> block at
 * the end of the section so the page loads fast but the data is
 * available on demand.
 *
 * Usage:
 *   node tools/generate-comparison-benchmark.mjs
 *   (also exposed as `npm run benchmark:update-comparison-page`,
 *   which runs the benchmark first)
 *
 * Exit codes:
 *   0 — comparison.html was up to date OR was successfully updated
 *   1 — could not find a benchmark report, or markers missing in
 *       comparison.html, or write failed
 */

import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");
const REPORTS_DIR = join(REPO_ROOT, "tests", "benchmark", "reports");
const COMPARISON_PATH = join(REPO_ROOT, "docs", "comparison.html");
const MARKER_START = "<!-- BENCHMARK_START";
const MARKER_END = "<!-- BENCHMARK_END -->";

// ── Pure utilities ───────────────────────────────────────────────────────

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function findLatestReport(dir) {
  const files = readdirSync(dir).filter((f) => f.endsWith("-muga.json"));
  if (files.length === 0) return null;
  files.sort();
  return join(dir, files[files.length - 1]);
}

// ── HTML builders ────────────────────────────────────────────────────────

/**
 * Renders the full block that lives between the BENCHMARK_START / END
 * markers. Pure: takes a parsed report object, returns the HTML string.
 */
export function renderBenchmarkSection(report) {
  // Note: the report's `generatedAt` field is intentionally NOT used
  // in the page output — its per-run drift would defeat the CI drift
  // gate that compares a freshly-generated page against the committed
  // one. The freshness signal users get from this page comes from the
  // git history of comparison.html itself, plus the snapshot hashes in
  // README-CONTRACT.txt (committed alongside each adapter refresh).
  const total = report.totalEntries || 0;
  const muga = {
    matched: report.matched || 0,
    matchRate: report.matchRate || 0,
  };

  // Order the competitors by match rate descending so the strongest
  // alternative shows up first. MUGA always renders separately.
  const competitorEntries = Object.entries(report.byCompetitor || {})
    .map(([name, data]) => ({ name, ...data }))
    .sort((a, b) => (b.matchRate || 0) - (a.matchRate || 0));

  const competitorRows = competitorEntries
    .map((c) => `
        <tr>
          <td><code>${escapeHtml(c.name)}</code></td>
          <td>${c.changedFromInput ?? 0}</td>
          <td>${c.matchedExpectedClean ?? 0} / ${c.withExpectedClean ?? 0}</td>
          <td><strong>${(c.matchRate ?? 0).toFixed(1)}%</strong></td>
        </tr>`)
    .join("");

  const categoryEntries = Object.entries(report.byCategory || {})
    .map(([name, data]) => ({ name, ...data }))
    .sort((a, b) => a.name.localeCompare(b.name));

  const categoryRows = categoryEntries
    .map((c) => `
          <tr>
            <td><code>${escapeHtml(c.name)}</code></td>
            <td>${c.total}</td>
            <td>${c.matched}</td>
            <td>${c.matchRate.toFixed(1)}%</td>
          </tr>`)
    .join("");

  const mismatchSection = (report.mismatches || []).length === 0
    ? `<p class="meta">No mismatches in the latest run. Every corpus entry produced the expected output for MUGA.</p>`
    : `<details>
          <summary>Per-URL mismatches (${report.mismatches.length})</summary>
          <ul>${report.mismatches.map((m) =>
            `<li><code>${escapeHtml(m.url || "")}</code>: expected <code>${escapeHtml(m.expected || "")}</code>, got <code>${escapeHtml(m.actual || "")}</code></li>`
          ).join("")}</ul>
        </details>`;

  return `<!-- BENCHMARK_START. Auto-generated by tools/generate-comparison-benchmark.mjs.
       Do not edit between these markers. Run \`npm run benchmark:update-comparison-page\`
       to refresh from the latest tests/benchmark/reports/*-muga.json. -->
  <h2>Auditable benchmark: corpus match rate</h2>
  <p>Numbers below come from running each tool against MUGA's open URL corpus (<a href="https://github.com/yocreoquesi/muga/tree/main/tests/benchmark/corpus" target="_blank" rel="noopener noreferrer">tests/benchmark/corpus/</a>). Each adapter consumes its own upstream rule set verbatim; no MUGA logic leaks in. The corpus + adapters + this report are all in the repo; reproduce locally with <code>npm run benchmark</code>.</p>

  <p class="meta">Corpus size: <strong>${total}</strong> URLs &nbsp;·&nbsp; <a href="https://github.com/yocreoquesi/muga/blob/main/tests/benchmark/competitors/README-CONTRACT.txt" target="_blank" rel="noopener noreferrer">Adapter contract + snapshot hashes</a> &nbsp;·&nbsp; <a href="https://github.com/yocreoquesi/muga/commits/main/docs/comparison.html" target="_blank" rel="noopener noreferrer">Last refreshed (git history)</a></p>

  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>URL cleaner</th>
          <th>URLs changed</th>
          <th>Matched expected output</th>
          <th>Match rate</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td><strong>MUGA</strong></td>
          <td>${muga.matched}</td>
          <td>${muga.matched} / ${total}</td>
          <td><strong>${muga.matchRate.toFixed(1)}%</strong></td>
        </tr>${competitorRows}
      </tbody>
    </table>
  </div>

  <p>Reading this table:</p>
  <ul>
    <li><strong>URLs changed</strong>: how many of the ${total} corpus entries the adapter modified at all (a sanity bound: an adapter that changes nothing always matches the rare "untouched" expectations).</li>
    <li><strong>Matched expected output</strong>: of the corpus entries that have an explicit <code>expectedClean</code>, how many the adapter produced verbatim. Higher = closer to MUGA's contract.</li>
    <li><strong>Match rate</strong>: the same number expressed as a percentage of corpus entries with <code>expectedClean</code>. The corpus is calibrated to MUGA's contract, so MUGA's rate is the upper bound; the gap to other tools shows where their rule sets diverge.</li>
  </ul>

  <details>
    <summary>MUGA match rate by corpus category</summary>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Category</th>
            <th>Total</th>
            <th>Matched</th>
            <th>Match rate</th>
          </tr>
        </thead>
        <tbody>${categoryRows}
        </tbody>
      </table>
    </div>
  </details>

  ${mismatchSection}
  <!-- BENCHMARK_END -->`;
}

/**
 * Replace the bytes between BENCHMARK_START and BENCHMARK_END in the
 * docs/comparison.html source. Returns the new source.
 *
 * Throws if either marker is missing — that's a contract violation:
 * comparison.html must always carry the markers, even if the section
 * is empty (placeholder content).
 */
export function injectBenchmarkSection(source, generated) {
  const startIdx = source.indexOf(MARKER_START);
  const endIdx = source.indexOf(MARKER_END);
  if (startIdx === -1) throw new Error(`marker not found: ${MARKER_START}`);
  if (endIdx === -1) throw new Error(`marker not found: ${MARKER_END}`);
  const before = source.slice(0, startIdx);
  const after = source.slice(endIdx + MARKER_END.length);
  return `${before}${generated}${after}`;
}

// ── CLI entry point ──────────────────────────────────────────────────────

function main() {
  const reportPath = findLatestReport(REPORTS_DIR);
  if (!reportPath) {
    process.stderr.write(
      `generate-comparison-benchmark: no benchmark report found under ${REPORTS_DIR}.\n` +
      `Run \`npm run benchmark\` first.\n`,
    );
    process.exit(1);
  }
  process.stdout.write(`generate-comparison-benchmark: source = ${reportPath}\n`);

  const report = JSON.parse(readFileSync(reportPath, "utf8"));
  const generated = renderBenchmarkSection(report);
  const original = readFileSync(COMPARISON_PATH, "utf8");
  let updated;
  try {
    updated = injectBenchmarkSection(original, generated);
  } catch (err) {
    process.stderr.write(`generate-comparison-benchmark: ${err.message}\n`);
    process.exit(1);
  }
  if (updated === original) {
    process.stdout.write(`generate-comparison-benchmark: comparison.html already up to date — no change\n`);
    return;
  }
  writeFileSync(COMPARISON_PATH, updated);
  process.stdout.write(`generate-comparison-benchmark: wrote ${COMPARISON_PATH}\n`);
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1].endsWith("generate-comparison-benchmark.mjs")) {
  main();
}
